  ('00000000-0000-4000-a023-000000000023', 'Customer and account volumes at go-live with growth', 'The solution holds 4.8 million customers and 2.4 million accounts at go-live, with 15% growth a year for five years.', 'non_functional', 'must', 'approved', 'Capacity test passes at five-year volumes', 'Data migration and quality', 'Priya Naidoo', 'Sizing must cover the planning horizon.', 'analysis', 'volumes'),
  ('00000000-0000-4000-a023-000000000024', 'Standing order run volume', 'The overnight run processes 1.2 million standing orders.', 'non_functional', 'must', 'draft', 'The run finishes inside its batch window at month-end volume', 'Payments and transfers', 'Ahmed Hassan', 'Month-end peaks carry the most standing orders.', 'test', 'volumes'),
  ('00000000-0000-4000-a023-000000000025', 'Branch customer search response', 'A branch customer search returns in under 3 seconds at peak.', 'non_functional', 'must', 'approved', '95% of searches return in under 3 seconds at peak load', 'Customer and digital channels', 'Ravi Pillai', 'Queues build when searches are slow.', 'test', 'performance'),
  ('00000000-0000-4000-a023-000000000026', 'Payment initiation response', 'Payment initiation completes in under 2 seconds end to end.', 'non_functional', 'must', 'approved', '95% of payments complete in under 2 seconds', 'Payments and transfers', 'Brian Otieno', 'Slow payments lead to duplicate attempts.', 'test', 'performance'),
  ('00000000-0000-4000-a023-000000000027', 'Two-factor sign-in', 'Customers on a new device and all privileged staff sign in with two factors.', 'non_functional', 'must', 'approved', 'Sign-in without the second factor is refused', 'Cybersecurity and access', 'Nadia Rahman', 'Account takeover is the main channel threat.', 'test', 'security'),
  ('00000000-0000-4000-a023-000000000028', 'Encryption at rest and in transit', 'Customer and account data is encrypted at rest and in transit.', 'non_functional', 'must', 'approved', 'Configuration review confirms encryption on every store and connection', 'Cybersecurity and access', 'Nadia Rahman', 'Required by policy and regulation.', 'inspection', 'security'),
  ('00000000-0000-4000-a023-000000000029', 'Static data load window', 'The static data load completes inside a 14-hour window.', 'non_functional', 'must', 'draft', 'Mock 2 static load completes inside 14 hours', 'Data migration and quality', 'Priya Naidoo', 'The freeze weekend has a fixed window.', 'test', 'migration'),
  ('00000000-0000-4000-a023-00000000002a', 'Take-over accounts reconcile to zero', 'Take-over and suspense accounts reconcile to zero after each mock.', 'non_functional', 'must', 'approved', 'Mock 3 ends with take-over and suspense at zero', 'Data migration and quality', 'Olivia Banda', 'Non-zero balances show lost or duplicated money.', 'analysis', 'migration'),
  ('00000000-0000-4000-a023-00000000002b', 'Address completeness', 'Active customers have a complete address in 85% or more of cases.', 'non_functional', 'should', 'draft', 'Profiling after Mock 2 shows 85% or more complete', 'Customer and digital channels', 'Amina Diallo', 'Statements and notices need a valid address.', 'analysis', 'data_requirements'),
  ('00000000-0000-4000-a023-00000000002c', 'Legacy keys kept as alternate keys', 'Legacy customer and account numbers are stored as alternate keys.', 'non_functional', 'must', 'approved', 'A sample of 500 legacy keys all resolve', 'Data migration and quality', 'Priya Naidoo', 'Old numbers must still find records.', 'inspection', 'data_requirements'),
  ('00000000-0000-4000-a023-00000000002d', 'Personal data stays in the agreed region', 'Customer personal data is stored and processed only in the agreed region.', 'non_functional', 'must', 'approved', 'Hosting and backup locations are in the agreed region', 'Cybersecurity and access', 'Nadia Rahman', 'Required by data protection law and contracts.', 'inspection', 'data_protection_privacy'),
  ('00000000-0000-4000-a023-00000000002e', 'Masked data in lower environments', 'Development and test environments hold masked data only.', 'non_functional', 'must', 'approved', 'Every refresh runs the approved masking rules', 'Environments and release', 'Ravi Pillai', 'Production personal data must not leave production.', 'inspection', 'data_protection_privacy'),
