  ('00000000-0000-4000-a026-00000000002c', 'Legacy keys kept as alternate keys', 'Legacy customer and account numbers are stored as alternate keys.', 'non_functional', 'must', 'approved', 'A sample of 500 legacy keys all resolve', 'Data migration and quality', 'Priya Naidoo', 'Old numbers must still find records.', 'inspection', 'data_requirements'),
  ('00000000-0000-4000-a026-00000000002d', 'Personal data stays in the agreed region', 'Customer personal data is stored and processed only in the agreed region.', 'non_functional', 'must', 'approved', 'Hosting and backup locations are in the agreed region', 'Cybersecurity and access', 'Nadia Rahman', 'Required by data protection law and contracts.', 'inspection', 'data_protection_privacy'),
