  ('00000000-0000-4000-a026-000000000031', 'Digital channel availability', 'Internet and mobile banking are available 99.9% of each month.', 'non_functional', 'must', 'approved', 'Monthly availability report shows 99.9% or more', 'Environments and release', 'Ravi Pillai', 'Customers expect banking at any hour.', 'analysis', 'availability_recovery'),
  ('00000000-0000-4000-a026-000000000032', 'Core recovery objectives', 'The core recovers within 4 hours with no more than 1 hour of data loss.', 'non_functional', 'must', 'draft', 'Recovery test restores within 4 hours and loses under 1 hour of data', 'Environments and release', 'Ravi Pillai', 'Required by the operational resilience policy.', 'test', 'availability_recovery'),
