SELECT v.id::uuid, '00000000-0000-4000-9003-000000000027'::uuid, TRUE, '', v.title, v.description, v.status, v.field_values::jsonb, p.id
FROM (VALUES
  ('00000000-0000-4000-a027-000000000001', 'UC-01 Open a current account at the branch', 'Open a current account at the branch. Primary actor: Teller.', 'approved', $j${"use_case_ref":"UC-01","primary_actor":"Teller","priority":"must","frequency_of_use":"many_daily","secondary_actors":"Customer\nCompliance officer","trigger_event":"A customer asks to open a current account at a branch.","preconditions":"Customer is identified and KYC has passed\nTeller is signed in with the teller role","postconditions":"Account is open with a 10-digit number\nCustomer receives the account details","main_flow":"1\tTeller\tSearches the customer by name or ID document\n2\tTeller\tChooses the current account product\n3\tSystem\tChecks KYC and restrictions\n4\tTeller\tCaptures mandate and signature images\n5\tSystem\tOpens the account and prints the welcome letter","alternative_flows":"3a\tSystem\tKYC expired — asks the teller to refresh documents first","business_rules":"A customer may hold only one basic current account","related_requirements":"One customer number across all channels\nSearch a customer by name, number, ID document or old number","related_screens_reports":"Customer search screen\nAccount opening screen"}$j$),
  ('00000000-0000-4000-a027-000000000002', 'UC-02 Register for internet banking', 'Register for internet banking. Primary actor: Customer.', 'approved', $j${"use_case_ref":"UC-02","primary_actor":"Customer","priority":"must","frequency_of_use":"daily","secondary_actors":"Identity provider","trigger_event":"A customer chooses to register on the internet banking site.","preconditions":"Customer has an active account\nCustomer has a registered mobile number","postconditions":"Customer can sign in to internet banking","main_flow":"1\tCustomer\tEnters customer number\n2\tSystem\tSends a one-time code to the registered mobile\n3\tCustomer\tEnters the code and sets a password\n4\tSystem\tActivates the profile and confirms by message","alternative_flows":"3a\tCustomer\tEnters a wrong code three times — registration locks for 24 hours","business_rules":"Codes expire after 5 minutes","related_requirements":"Register for internet banking with a one-time code\nTwo-factor sign-in","related_screens_reports":"Registration page"}$j$),
  ('00000000-0000-4000-a027-000000000003', 'UC-03 Make a domestic transfer', 'Make a domestic transfer. Primary actor: Customer.', 'approved', $j${"use_case_ref":"UC-03","primary_actor":"Customer","priority":"must","frequency_of_use":"many_daily","secondary_actors":"Payment scheme","trigger_event":"A signed-in customer chooses to pay someone.","preconditions":"Customer is signed in\nAccount has funds","postconditions":"Payment is sent in the next scheme cycle\nCustomer sees the payment in history","main_flow":"1\tCustomer\tChooses the account and beneficiary\n2\tCustomer\tEnters amount and reference\n3\tSystem\tChecks the channel limit and balance\n4\tCustomer\tConfirms with the second factor\n5\tSystem\tSends the payment and shows the confirmation","alternative_flows":"3a\tSystem\tAmount is over the limit — refuses and shows the limit","business_rules":"Limits follow the signed limit matrix","related_requirements":"Make a domestic credit transfer within channel limits\nPayment limits by channel and customer type","related_screens_reports":"Payments page"}$j$),
  ('00000000-0000-4000-a027-000000000004', 'UC-04 Set up a standing order', 'Set up a standing order. Primary actor: Customer.', 'approved', $j${"use_case_ref":"UC-04","primary_actor":"Customer","priority":"should","frequency_of_use":"weekly","secondary_actors":"Payment scheme","trigger_event":"A customer wants to pay the same amount regularly.","preconditions":"Customer is signed in","postconditions":"Standing order is active and runs on its first date","main_flow":"1\tCustomer\tChooses beneficiary, amount and frequency\n2\tCustomer\tChooses the first and last dates\n3\tSystem\tValidates the dates and limit\n4\tSystem\tCreates the standing order","alternative_flows":"3a\tSystem\tFirst date is in the past — asks for a new date","business_rules":"A standing order cannot start on a scheme holiday","related_requirements":"Create, change and cancel a standing order","related_screens_reports":"Standing orders page"}$j$),
  ('00000000-0000-4000-a027-000000000005', 'UC-05 Find a customer at the branch', 'Find a customer at the branch. Primary actor: Teller.', 'approved', $j${"use_case_ref":"UC-05","primary_actor":"Teller","priority":"must","frequency_of_use":"many_daily","secondary_actors":"Contact centre agent","trigger_event":"A customer arrives at the counter.","preconditions":"Teller is signed in","postconditions":"Teller sees the customer view","main_flow":"1\tTeller\tEnters a name, number, ID document or old number\n2\tSystem\tShows matching customers\n3\tTeller\tOpens the customer view","alternative_flows":"2a\tSystem\tOld number found — opens the surviving customer","business_rules":"Search results show masked ID numbers","related_requirements":"Search a customer by name, number, ID document or old number\nBranch customer search response","related_screens_reports":"Customer search screen"}$j$),
  ('00000000-0000-4000-a027-000000000006', 'UC-06 Approve a limit override', 'Approve a limit override. Primary actor: Credit officer.', 'approved', $j${"use_case_ref":"UC-06","primary_actor":"Credit officer","priority":"should","frequency_of_use":"daily","secondary_actors":"Relationship manager","trigger_event":"A relationship manager asks for a temporary limit increase.","preconditions":"Request has a reason and expiry date","postconditions":"Override is active until its expiry\nThe approval is logged","main_flow":"1\tRelationship manager\tRaises the override request\n2\tSystem\tRoutes it to a credit officer\n3\tCredit officer\tReviews and approves\n4\tSystem\tApplies the override and logs the approver","alternative_flows":"3a\tCredit officer\tRejects with a reason — requester is notified","business_rules":"An officer cannot approve their own request","related_requirements":"Change audit trail","related_screens_reports":"Limit override screen"}$j$),
  ('00000000-0000-4000-a027-000000000007', 'UC-07 Repair a failed payment', 'Repair a failed payment. Primary actor: Payments operator.', 'draft', $j${"use_case_ref":"UC-07","primary_actor":"Payments operator","priority":"must","frequency_of_use":"daily","secondary_actors":"Payments supervisor","trigger_event":"A payment fails or is returned by the scheme.","preconditions":"Payment is on the repair queue","postconditions":"Payment is resent or returned to the customer","main_flow":"1\tPayments operator\tOpens the repair queue item\n2\tPayments operator\tCorrects the beneficiary details\n3\tPayments supervisor\tApproves the repair\n4\tSystem\tResends the payment once","alternative_flows":"3a\tPayments supervisor\tRejects — the payment is returned to the customer account","business_rules":"Every repair needs a second person","related_requirements":"Repair queue for failed and returned payments","related_screens_reports":"Repair queue"}$j$),
  ('00000000-0000-4000-a027-000000000008', 'UC-08 Run the end-of-day reconciliation', 'Run the end-of-day reconciliation. Primary actor: Finance analyst.', 'draft', $j${"use_case_ref":"UC-08","primary_actor":"Finance analyst","priority":"must","frequency_of_use":"daily","secondary_actors":"Financial controller","trigger_event":"End of day processing completes.","preconditions":"End of day has finished","postconditions":"Reconciliation report is signed off","main_flow":"1\tSystem\tProduces control totals by product and currency\n2\tFinance analyst\tCompares totals to the ledger\n3\tFinance analyst\tExplains any breaks\n4\tFinancial controller\tSigns off the report","alternative_flows":"3a\tFinance analyst\tBreak cannot be explained — raises an incident","business_rules":"Breaks over the tolerance stop sign-off","related_requirements":"Reconcile migrated balances by product and currency","related_screens_reports":"Reconciliation report"}$j$),
  ('00000000-0000-4000-a027-000000000009', 'UC-09 Remove a leaver''s access', 'Remove a leaver''s access. Primary actor: Service desk analyst.', 'draft', $j${"use_case_ref":"UC-09","primary_actor":"Service desk analyst","priority":"must","frequency_of_use":"weekly","secondary_actors":"Line manager\nHR system","trigger_event":"HR records a leaver.","preconditions":"Leaver record exists in HR","postconditions":"All access is removed the same day","main_flow":"1\tHR system\tSends the leaver in the daily feed\n2\tSystem\tDisables the identity\n3\tService desk analyst\tConfirms privileged accounts are closed\n4\tSystem\tLogs the removal","alternative_flows":"2a\tSystem\tLeaver has privileged access — alerts the security team","business_rules":"Leavers lose access by the end of their last day","related_requirements":"Revoke a leaver's access the day they leave\nChange audit trail","related_screens_reports":"Access review screen"}$j$),
  ('00000000-0000-4000-a027-00000000000a', 'UC-10 View a mandate image before paying out', 'View a mandate image before paying out. Primary actor: Teller.', 'draft', $j${"use_case_ref":"UC-10","primary_actor":"Teller","priority":"must","frequency_of_use":"many_daily","secondary_actors":"Document store","trigger_event":"A customer asks to withdraw cash over the teller limit.","preconditions":"Customer is identified","postconditions":"Teller has checked the signature","main_flow":"1\tTeller\tOpens the account\n2\tTeller\tOpens the mandate image\n3\tSystem\tRetrieves the image from the document store\n4\tTeller\tCompares the signature and continues","alternative_flows":"3a\tSystem\tImage not available — teller asks a supervisor to authorise","business_rules":"Only teller and supervisor roles can open images","related_requirements":"Show mandate and signature images to branch staff","related_screens_reports":"Mandate image viewer"}$j$)
) AS v(id, title, description, status, field_values)
CROSS JOIN pp p
ON CONFLICT (id) DO NOTHING;

WITH pp AS (
  SELECT id FROM sim.practice_projects WHERE project_code = 'SEED592-PP-01' AND NOT COALESCE(is_deleted, FALSE) LIMIT 1
)
INSERT INTO sim.local_register_records
  (id, register_id, is_system_register, display_id, title, description, status, field_values, record_project_id)
SELECT v.id::uuid, '00000000-0000-4000-9003-000000000028'::uuid, TRUE, '', v.title, v.description, v.status, v.field_values::jsonb, p.id
FROM (VALUES
  ('00000000-0000-4000-a028-000000000001', 'Customer and digital channels – Business Requirements Document', 'Business Requirements Document for customer and digital channels on the Northbridge Bank technology programme. Owner: Amina Diallo.', 'draft', $j${"document_type":"brd","document_reference":"NRB-BRD-01","document_version":"0.9","document_owner":"Amina Diallo","business_owner":"Nomvula Khumalo","next_review_date":"2026-11-16","purpose":"Sets out what the business needs from customer and digital channels on the Northbridge Bank technology programme and why. Once signed it is the baseline for design, testing and change control.","requirements_overview":"Delivery of customer master data and the internet, mobile and branch channels for the Northbridge Bank technology programme. The requirements are held in the project's Requirements register so design, testing and traceability use the same list; the chapters below show them.","in_scope":"Retail and SME customer master\nCorporate customer master from the second legacy instance\nInternet banking registration\nMobile banking registration\nBranch teller customer search\nContact centre customer view","out_of_scope":"Card plastic personalisation\nMarketing campaign tool\nLoyalty scheme\nInsurance product origination\nWealth advisory portal","summary_of_requirements":"The project holds 12 business, 22 functional and 20 non-functional requirements, plus technical, regulatory and other requirements. Most are Must; deferred items are marked in the register.","assumptions":"Both legacy instances are profiled before Mock 2\nThe surviving record is the one with the most complete KYC data\nCustomers accept a new customer number where numbers clash\nBranch staff are trained before the dress rehearsal\nStatement templates are approved by the business","constraints":"Customer numbers must be unique across both legacy instances\nKYC fields are mandatory before a customer can be loaded\nAddress completeness target is 85%\nImages must be linked before the channel is opened\nThe load window is the weekend of 10–12 April 2027","dependencies":"Customer deduplication rules signed off\nKYC repository extract granted\nDocument image storage decision\nTarget customer products configured","glossary":"BRD\tBusiness Requirements Document — what the business needs and why\nFRS\tFunctional Requirements Specification — how the solution behaves\nMoSCoW\tPriority scale: Must, Should, Could, Won't (this release)\nTarget core\tThe new core banking platform that replaces both legacy cores","appendices":"Customer and digital channels delivery overview\tDelivery Overview – Customer and digital channels\nCustomer and digital channels roadmap\tNRB-RM-01","version_history":"0.1\t2026-06-01\tAmina Diallo\tFirst draft from the template\n0.5\t2026-08-03\tNomvula Khumalo\tBusiness review comments\n0.9\t2026-10-26\tAmina Diallo\tReady for sign-off","related_documents":"NRB-RM-01 – Customer and digital channels roadmap\nNRB-SA-01 – Customer and digital channels solution architecture\nDelivery Overview – Customer and digital channels"}$j$),
  ('00000000-0000-4000-a028-000000000002', 'Payments and transfers – Functional Requirements Specification', 'Functional Requirements Specification for payments and transfers on the Northbridge Bank technology programme. Owner: Ahmed Hassan.', 'draft', $j${"document_type":"frs","document_reference":"NRB-FRS-02","document_version":"0.9","document_owner":"Ahmed Hassan","business_owner":"Catherine Mwangi","next_review_date":"2026-11-18","purpose":"Specifies how the solution must behave for payments and transfers to meet the signed business requirements. It is the basis for design, build and system testing.","requirements_overview":"Delivery of domestic payments, standing orders and internal transfers onto the target platform. The requirements are held in the project's Requirements register so design, testing and traceability use the same list; the chapters below show them.","in_scope":"Domestic credit transfers\nInternal account transfers\nStanding orders\nFuture-dated payments\nPayment limits by channel\nSettlement timetable","out_of_scope":"Card authorisation\nATM cash\nCheque clearing replacement\nCross-border correspondent banking rebuild\nCash-in-transit","summary_of_requirements":"The project holds 12 business, 22 functional and 20 non-functional requirements, plus technical, regulatory and other requirements. Most are Must; deferred items are marked in the register.","assumptions":"The scheme timetable does not change before go-live\nStanding orders are recreated, not replayed from history\nBoth legacy instances use the same value-date rule\nPayment limits are signed by the business before UAT\nThe repair queue is staffed for hypercare","constraints":"Scheme cut-off cannot move\nSettlement must balance on the night\nStanding orders with an end date in the past are excluded\nDual control stays on the repair queue\nPayment files are not accepted during the freeze","dependencies":"Customer and account numbers mapped\nScheme gateway certificate renewed\nLimit matrix signed\nSettlement accounts configured","glossary":"BRD\tBusiness Requirements Document — what the business needs and why\nFRS\tFunctional Requirements Specification — how the solution behaves\nMoSCoW\tPriority scale: Must, Should, Could, Won't (this release)\nTarget core\tThe new core banking platform that replaces both legacy cores","appendices":"Payments and transfers delivery overview\tDelivery Overview – Payments and transfers\nPayments and transfers roadmap\tNRB-RM-02","version_history":"0.1\t2026-06-01\tAhmed Hassan\tFirst draft from the template\n0.5\t2026-08-03\tCatherine Mwangi\tBusiness review comments\n0.9\t2026-10-26\tAhmed Hassan\tReady for sign-off","related_documents":"NRB-RM-02 – Payments and transfers roadmap\nNRB-SA-02 – Payments and transfers solution architecture\nDelivery Overview – Payments and transfers"}$j$),
  ('00000000-0000-4000-a028-000000000003', 'Lending, limits and collateral – Business Requirements Document', 'Business Requirements Document for lending, limits and collateral on the Northbridge Bank technology programme. Owner: Joy Akinyi.', 'draft', $j${"document_type":"brd","document_reference":"NRB-BRD-03","document_version":"0.9","document_owner":"Joy Akinyi","business_owner":"Daniel Okafor","next_review_date":"2026-11-11","purpose":"Sets out what the business needs from lending, limits and collateral on the Northbridge Bank technology programme and why. Once signed it is the baseline for design, testing and change control.","requirements_overview":"Delivery of loans, limits and collateral, including overdue bills and the expired-limit rule. The requirements are held in the project's Requirements register so design, testing and traceability use the same list; the chapters below show them.","in_scope":"Retail loan arrangements\nCorporate loan arrangements\nOverdue and due bills\nAccrued interest on loans\nLimit records\nExpired limits still linked to a contract","out_of_scope":"New scorecard build\nDebt collection agency files\nSecuritisation\nSyndicated loan agency\nTrade finance instruments","summary_of_requirements":"The project holds 12 business, 22 functional and 20 non-functional requirements, plus technical, regulatory and other requirements. Most are Must; deferred items are marked in the register.","assumptions":"Schedules are regenerated from the migrated frequency\nThe expired-limit rule is expiry plus one day, with the original date kept\nOne liquidation account is allowed per customer per currency\nCollateral rights load before collateral items\nPast-due date becomes the bill date","constraints":"A loan cannot load before its customer and account\nCollateral cannot load before its right\nAgeing must not reset to zero\nExpired limits cannot be dropped while a contract is live\nTake-over accounts must be zero after reconciliation","dependencies":"Customer numbers mapped\nExpired-limit rule signed by credit\nRepayment account rule signed\nCollateral identifier format agreed","glossary":"BRD\tBusiness Requirements Document — what the business needs and why\nFRS\tFunctional Requirements Specification — how the solution behaves\nMoSCoW\tPriority scale: Must, Should, Could, Won't (this release)\nTarget core\tThe new core banking platform that replaces both legacy cores","appendices":"Lending, limits and collateral delivery overview\tDelivery Overview – Lending, limits and collateral\nLending, limits and collateral roadmap\tNRB-RM-03","version_history":"0.1\t2026-06-01\tJoy Akinyi\tFirst draft from the template\n0.5\t2026-08-03\tDaniel Okafor\tBusiness review comments\n0.9\t2026-10-26\tJoy Akinyi\tReady for sign-off","related_documents":"NRB-RM-03 – Lending, limits and collateral roadmap\nNRB-SA-03 – Lending, limits and collateral solution architecture\nDelivery Overview – Lending, limits and collateral"}$j$),
  ('00000000-0000-4000-a028-000000000004', 'Deposits and accounts – Functional Requirements Specification', 'Functional Requirements Specification for deposits and accounts on the Northbridge Bank technology programme. Owner: Catherine Mwangi.', 'draft', $j${"document_type":"frs","document_reference":"NRB-FRS-04","document_version":"0.9","document_owner":"Catherine Mwangi","business_owner":"Nomvula Khumalo","next_review_date":"2026-11-17","purpose":"Specifies how the solution must behave for deposits and accounts to meet the signed business requirements. It is the basis for design, build and system testing.","requirements_overview":"Delivery of current accounts, savings and term deposits, including balances and accruals. The requirements are held in the project's Requirements register so design, testing and traceability use the same list; the chapters below show them.","in_scope":"Current accounts\nSavings accounts\nTerm deposits\nDeposit balances and accruals\nDormant accounts over five years\nMatured deposits that still hold a balance","out_of_scope":"Safe custody\nNew savings product launch\nPrize-linked savings\nChildren account campaign\nBrokerage cash accounts","summary_of_requirements":"The project holds 12 business, 22 functional and 20 non-functional requirements, plus technical, regulatory and other requirements. Most are Must; deferred items are marked in the register.","assumptions":"Three legacy current-account products become one target product\nInstance 2 numbers become 10 digits with a check digit\nDormant means no customer-initiated transaction for five years\nUnclaimed balances move under the existing regulation\nMatured deposits are paid out or rolled, not migrated as running","constraints":"No account closures in the week before go-live\nA zero-balance account marked for closure is excluded\nAlternate keys are mandatory for instance 2\nAccrual value date cannot be the original accrual date\nProduct mapping cannot change after Mock 2 without a new approval","dependencies":"Product mapping approved\n10-digit account standard agreed\nDormant population identified\nMatured-deposit population identified","glossary":"BRD\tBusiness Requirements Document — what the business needs and why\nFRS\tFunctional Requirements Specification — how the solution behaves\nMoSCoW\tPriority scale: Must, Should, Could, Won't (this release)\nTarget core\tThe new core banking platform that replaces both legacy cores","appendices":"Deposits and accounts delivery overview\tDelivery Overview – Deposits and accounts\nDeposits and accounts roadmap\tNRB-RM-04","version_history":"0.1\t2026-06-01\tCatherine Mwangi\tFirst draft from the template\n0.5\t2026-08-03\tNomvula Khumalo\tBusiness review comments\n0.9\t2026-10-26\tCatherine Mwangi\tReady for sign-off","related_documents":"NRB-RM-04 – Deposits and accounts roadmap\nNRB-SA-04 – Deposits and accounts solution architecture\nDelivery Overview – Deposits and accounts"}$j$),
  ('00000000-0000-4000-a028-000000000005', 'Data migration and quality – Business Requirements Document', 'Business Requirements Document for data migration and quality on the Northbridge Bank technology programme. Owner: Priya Naidoo.', 'draft', $j${"document_type":"brd","document_reference":"NRB-BRD-05","document_version":"0.9","document_owner":"Priya Naidoo","business_owner":"Amina Diallo","next_review_date":"2026-11-13","purpose":"Sets out what the business needs from data migration and quality on the Northbridge Bank technology programme and why. Once signed it is the baseline for design, testing and change control.","requirements_overview":"Cross-cutting delivery of extraction, cleansing, transformation, mock runs and reconciliation for the programme. The requirements are held in the project's Requirements register so design, testing and traceability use the same list; the chapters below show them.","in_scope":"Source profiling\nExtraction from both legacy instances\nCleansing at source\nTransformation rules\nMock runs\nDress rehearsal","out_of_scope":"Building the target platform\nCard scheme certification\nGeneral ledger replacement\nStaff identity directory rebuild\nA new data warehouse","summary_of_requirements":"The project holds 12 business, 22 functional and 20 non-functional requirements, plus technical, regulatory and other requirements. Most are Must; deferred items are marked in the register.","assumptions":"Three mock runs and one dress rehearsal are enough\nCleansing is done in the source, not in the load\nThe file layout is plain text, one record per line\nDates travel as YYYYMMDD\nControl totals come from the final close of business","constraints":"The April 2027 weekend is fixed\nPersonal data stays in the residency region\nA population cannot load before its predecessor\nSeverity-1 defects block the next mock\nTake-over accounts must finish at zero","dependencies":"Source access granted\nFile layout signed\nTake-over accounts opened\nData owners named","glossary":"BRD\tBusiness Requirements Document — what the business needs and why\nFRS\tFunctional Requirements Specification — how the solution behaves\nMoSCoW\tPriority scale: Must, Should, Could, Won't (this release)\nTarget core\tThe new core banking platform that replaces both legacy cores","appendices":"Data migration and quality delivery overview\tDelivery Overview – Data migration and quality\nData migration and quality roadmap\tNRB-RM-05","version_history":"0.1\t2026-06-01\tPriya Naidoo\tFirst draft from the template\n0.5\t2026-08-03\tAmina Diallo\tBusiness review comments\n0.9\t2026-10-26\tPriya Naidoo\tReady for sign-off","related_documents":"NRB-RM-05 – Data migration and quality roadmap\nNRB-SA-05 – Data migration and quality solution architecture\nDelivery Overview – Data migration and quality"}$j$),
  ('00000000-0000-4000-a028-000000000006', 'Integration and interfaces – Functional Requirements Specification', 'Functional Requirements Specification for integration and interfaces on the Northbridge Bank technology programme. Owner: Brian Otieno.', 'draft', $j${"document_type":"frs","document_reference":"NRB-FRS-06","document_version":"0.9","document_owner":"Brian Otieno","business_owner":"Ravi Pillai","next_review_date":"2026-11-19","purpose":"Specifies how the solution must behave for integration and interfaces to meet the signed business requirements. It is the basis for design, build and system testing.","requirements_overview":"Delivery of the interfaces the target platform needs from channels, cards, finance, documents and the user store. The requirements are held in the project's Requirements register so design, testing and traceability use the same list; the chapters below show them.","in_scope":"Internet banking interface\nMobile banking interface\nBranch teller interface\nContact centre interface\nCard status cross-check\nDocument image retrieval","out_of_scope":"A new integration platform product selection\nOpen-banking directory build\nCard scheme certification\nATM switch replacement\nPoint of sale acquiring","summary_of_requirements":"The project holds 12 business, 22 functional and 20 non-functional requirements, plus technical, regulatory and other requirements. Most are Must; deferred items are marked in the register.","assumptions":"Existing channels are reused and pointed at the target\nThe card system is not migrated; only status is cross-checked\nThe finance system stays and sends a file\nCertificates can be renewed without a scheme change\nOne dashboard covers every in-scope interface","constraints":"SIT entry dates are fixed on the integration plan\nA missing certificate blocks that interface\nCard numbers are not stored on the dashboard\nThe trial-balance file is after close of business\nReplay cannot create a second payment","dependencies":"Interface contracts approved\nSIT slots booked\nCertificates inventoried\nDashboard built","glossary":"BRD\tBusiness Requirements Document — what the business needs and why\nFRS\tFunctional Requirements Specification — how the solution behaves\nMoSCoW\tPriority scale: Must, Should, Could, Won't (this release)\nTarget core\tThe new core banking platform that replaces both legacy cores","appendices":"Integration and interfaces delivery overview\tDelivery Overview – Integration and interfaces\nIntegration and interfaces roadmap\tNRB-RM-06","version_history":"0.1\t2026-06-01\tBrian Otieno\tFirst draft from the template\n0.5\t2026-08-03\tRavi Pillai\tBusiness review comments\n0.9\t2026-10-26\tBrian Otieno\tReady for sign-off","related_documents":"NRB-RM-06 – Integration and interfaces roadmap\nNRB-SA-06 – Integration and interfaces solution architecture\nDelivery Overview – Integration and interfaces"}$j$),
  ('00000000-0000-4000-a028-000000000007', 'Cybersecurity and access – Business Requirements Document', 'Business Requirements Document for cybersecurity and access on the Northbridge Bank technology programme. Owner: Nadia Rahman.', 'draft', $j${"document_type":"brd","document_reference":"NRB-BRD-07","document_version":"0.9","document_owner":"Nadia Rahman","business_owner":"Daniel Okafor","next_review_date":"2026-11-24","purpose":"Sets out what the business needs from cybersecurity and access on the Northbridge Bank technology programme and why. Once signed it is the baseline for design, testing and change control.","requirements_overview":"Delivery of user access, recertification and the security controls required before go-live. Currently on hold. The requirements are held in the project's Requirements register so design, testing and traceability use the same list; the chapters below show them.","in_scope":"Bank user profiles\nUser groups and roles\nLine-manager recertification\nPrivileged access\nJoiner, mover and leaver handling\nAuthentication for staff","out_of_scope":"Customer authentication redesign\nA new identity product selection\nBuilding access\nCard PIN platform\nEndpoint replacement","summary_of_requirements":"The project holds 12 business, 22 functional and 20 non-functional requirements, plus technical, regulatory and other requirements. Most are Must; deferred items are marked in the register.","assumptions":"Line managers recertify their own staff\nThe identity directory is a source, not a system being replaced\nPrivileged access is a separate list\nLeavers are removed in the source before extract\nCustomer sign-in is owned by the channels delivery","constraints":"User load cannot start before recertification\nThe freeze date does not move for this workstream alone\nPrivileged access requires two approvers\nPersonal data in access logs follows the retention schedule\nA leaver cannot be loaded","dependencies":"Recertification date agreed\nLine-manager list confirmed\nPrivileged roles listed\nLeaver extract defined","glossary":"BRD\tBusiness Requirements Document — what the business needs and why\nFRS\tFunctional Requirements Specification — how the solution behaves\nMoSCoW\tPriority scale: Must, Should, Could, Won't (this release)\nTarget core\tThe new core banking platform that replaces both legacy cores","appendices":"Cybersecurity and access delivery overview\tDelivery Overview – Cybersecurity and access\nCybersecurity and access roadmap\tNRB-RM-07","version_history":"0.1\t2026-06-01\tNadia Rahman\tFirst draft from the template\n0.5\t2026-08-03\tDaniel Okafor\tBusiness review comments\n0.9\t2026-10-26\tNadia Rahman\tReady for sign-off","related_documents":"NRB-RM-07 – Cybersecurity and access roadmap\nNRB-SA-07 – Cybersecurity and access solution architecture\nDelivery Overview – Cybersecurity and access"}$j$),
  ('00000000-0000-4000-a028-000000000008', 'Environments and release – Functional Requirements Specification', 'Functional Requirements Specification for environments and release on the Northbridge Bank technology programme. Owner: Ravi Pillai.', 'draft', $j${"document_type":"frs","document_reference":"NRB-FRS-08","document_version":"0.9","document_owner":"Ravi Pillai","business_owner":"Brian Otieno","next_review_date":"2026-11-18","purpose":"Specifies how the solution must behave for environments and release to meet the signed business requirements. It is the basis for design, build and system testing.","requirements_overview":"Delivery of the environment path from development through dress rehearsal, production and recovery, and the release calendar that uses it. The requirements are held in the project's Requirements register so design, testing and traceability use the same list; the chapters below show them.","in_scope":"Development environment\nTest environment\nSystem integration environment\nUser acceptance environment\nPre-production\nProduction cutover runbook","out_of_scope":"A new data centre build\nEnd-user device replacement\nNetwork redesign\nCloud provider selection\nProduction support model","summary_of_requirements":"The project holds 12 business, 22 functional and 20 non-functional requirements, plus technical, regulatory and other requirements. Most are Must; deferred items are marked in the register.","assumptions":"Existing hosting is reused\nProduction-like data is masked except in dress rehearsal under approval\nOne calendar is enough\nRecovery is a restore test, not a second data centre project\nTeams will book if the booking is easier than asking in a chat","constraints":"The dress rehearsal date is fixed once booked\nMasked data is the default\nProduction access is named people only\nTwo mocks cannot share an environment\nA refresh during execution is refused","dependencies":"Hosting capacity confirmed\nMasking approach agreed\nApril weekend reserved\nDress rehearsal slot requested","glossary":"BRD\tBusiness Requirements Document — what the business needs and why\nFRS\tFunctional Requirements Specification — how the solution behaves\nMoSCoW\tPriority scale: Must, Should, Could, Won't (this release)\nTarget core\tThe new core banking platform that replaces both legacy cores","appendices":"Environments and release delivery overview\tDelivery Overview – Environments and release\nEnvironments and release roadmap\tNRB-RM-08","version_history":"0.1\t2026-06-01\tRavi Pillai\tFirst draft from the template\n0.5\t2026-08-03\tBrian Otieno\tBusiness review comments\n0.9\t2026-10-26\tRavi Pillai\tReady for sign-off","related_documents":"NRB-RM-08 – Environments and release roadmap\nNRB-SA-08 – Environments and release solution architecture\nDelivery Overview – Environments and release"}$j$),
  ('00000000-0000-4000-a028-000000000009', 'Operational readiness and hypercare – Business Requirements Document', 'Business Requirements Document for operational readiness and hypercare on the Northbridge Bank technology programme. Owner: Linda Zhou.', 'draft', $j${"document_type":"brd","document_reference":"NRB-BRD-09","document_version":"0.9","document_owner":"Linda Zhou","business_owner":"Catherine Mwangi","next_review_date":"2026-11-20","purpose":"Sets out what the business needs from operational readiness and hypercare on the Northbridge Bank technology programme and why. Once signed it is the baseline for design, testing and change control.","requirements_overview":"Delivery of the support model, runbooks, monitoring handover and the hypercare period after go-live. The requirements are held in the project's Requirements register so design, testing and traceability use the same list; the chapters below show them.","in_scope":"Support model\nRunbooks for the cutover weekend\nHypercare roster\nDaily hypercare bridge\nSeverity scale for hypercare\nMonitoring handover","out_of_scope":"A new service-desk product\nBranch refurbishment\nA 24-hour contact centre build\nVendor contract renegotiation\nProduction data centre build","summary_of_requirements":"The project holds 12 business, 22 functional and 20 non-functional requirements, plus technical, regulatory and other requirements. Most are Must; deferred items are marked in the register.","assumptions":"Hypercare lasts four weeks\nThe existing service desk is the front door\nRunbooks are steps with an expected result\nNight shifts are required for the first week only\nMonitoring is handed over, not rebuilt","constraints":"Hypercare cannot be staffed by unnamed roles\nA runbook that has not been walked through does not count\nThe first week has night cover\nExit criteria are set before go-live\nThe bridge is every business day in hypercare","dependencies":"Support model drafted\nRunbook template agreed\nRoster owners identified\nMonitoring owner named","glossary":"BRD\tBusiness Requirements Document — what the business needs and why\nFRS\tFunctional Requirements Specification — how the solution behaves\nMoSCoW\tPriority scale: Must, Should, Could, Won't (this release)\nTarget core\tThe new core banking platform that replaces both legacy cores","appendices":"Operational readiness and hypercare delivery overview\tDelivery Overview – Operational readiness and hypercare\nOperational readiness and hypercare roadmap\tNRB-RM-09","version_history":"0.1\t2026-06-01\tLinda Zhou\tFirst draft from the template\n0.5\t2026-08-03\tCatherine Mwangi\tBusiness review comments\n0.9\t2026-10-26\tLinda Zhou\tReady for sign-off","related_documents":"NRB-RM-09 – Operational readiness and hypercare roadmap\nNRB-SA-09 – Operational readiness and hypercare solution architecture\nDelivery Overview – Operational readiness and hypercare"}$j$),
  ('00000000-0000-4000-a028-00000000000a', 'Regulatory reporting – Functional Requirements Specification', 'Functional Requirements Specification for regulatory reporting. Superseded: the reporting workstream closed on 30 September 2026; kept for reference.', 'superseded', $j${"document_type":"frs","document_reference":"NRB-FRS-10","document_version":"1.0","document_owner":"Olivia Banda","business_owner":"Olivia Banda","next_review_date":"2027-03-31","purpose":"Specifies how the solution must behave for regulatory reporting to meet the signed business requirements. It is the basis for design, build and system testing.","requirements_overview":"Completed delivery of the report-line mapping that lets finance keep the existing reporting tool across the migration. The requirements are held in the project's Requirements register so design, testing and traceability use the same list; the chapters below show them.","in_scope":"Report-line map from the trial balance\nCurrency and company mapping\nFirst mock cross-check\nEvidence pack for finance\nNamed owner per report family\nDifference account treatment","out_of_scope":"A new reporting tool\nPrudential return redesign\nTax engine replacement\nManagement information warehouse\nBoard pack redesign","summary_of_requirements":"The project holds 12 business, 22 functional and 20 non-functional requirements, plus technical, regulatory and other requirements. Most are Must; deferred items are marked in the register.","assumptions":"The finance system stays\nThe chart of accounts does not change for go-live\nLast year of report lines is the scope\nDifferences use account 14918 as already agreed for the journals\nThe controller is the signer","constraints":"No new reporting tool\nThe map cannot drop a line used in the last year\nDifferences have one account\nSign-off is the controller, not the project\nThe guide stays short","dependencies":"Trial balance owner\nList of report lines from the last year\nDifference account agreed\nController availability","glossary":"BRD\tBusiness Requirements Document — what the business needs and why\nFRS\tFunctional Requirements Specification — how the solution behaves\nMoSCoW\tPriority scale: Must, Should, Could, Won't (this release)\nTarget core\tThe new core banking platform that replaces both legacy cores","appendices":"Regulatory reporting delivery overview\tDelivery Overview – Regulatory reporting\nRegulatory reporting roadmap\tNRB-RM-10","version_history":"0.1\t2026-06-01\tOlivia Banda\tFirst draft from the template\n0.5\t2026-08-03\tOlivia Banda\tBusiness review comments\n1.0\t2026-09-28\tOlivia Banda\tFinal; workstream closed","related_documents":"NRB-RM-10 – Regulatory reporting roadmap\nNRB-SA-10 – Regulatory reporting solution architecture\nDelivery Overview – Regulatory reporting"}$j$)
) AS v(id, title, description, status, field_values)
CROSS JOIN pp p
ON CONFLICT (id) DO NOTHING;

-- ── Check ────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_req INT; v_uc INT; v_spec INT; v_sim_req INT; v_sim_uc INT; v_sim_spec INT; v_codes INT;
BEGIN
  SELECT COUNT(*), COUNT(*) FILTER (WHERE COALESCE(requirement_code, '') <> '') INTO v_req, v_codes
    FROM public.requirements_register WHERE id::text LIKE '00000000-0000-4000-a023-%';
  SELECT COUNT(*) INTO v_uc FROM public.local_register_records WHERE id::text LIKE '00000000-0000-4000-a024-%';
  SELECT COUNT(*) INTO v_spec FROM public.local_register_records WHERE id::text LIKE '00000000-0000-4000-a025-%';
  SELECT COUNT(*) INTO v_sim_req FROM sim.requirements_register WHERE id::text LIKE '00000000-0000-4000-a026-%';
  SELECT COUNT(*) INTO v_sim_uc FROM sim.local_register_records WHERE id::text LIKE '00000000-0000-4000-a027-%';
  SELECT COUNT(*) INTO v_sim_spec FROM sim.local_register_records WHERE id::text LIKE '00000000-0000-4000-a028-%';
  RAISE NOTICE 'v1393 Platform: % requirements (% with codes), % use cases, % specifications (expected 60, 10, 10)', v_req, v_codes, v_uc, v_spec;
  RAISE NOTICE 'v1393 Simulator: % requirements, % use cases, % specifications (expected 60, 10, 10; 0 if SEED592-PP-01 is missing)', v_sim_req, v_sim_uc, v_sim_spec;
END $$;
